// 汇总所有楼幢（含已点选/未点选）的房屋为扁平列表，用于「列表视图」多幢房屋统一核对。
// 性能：结果按 treeDataVersion（树结构版本）缓存，勾选变化不再触发重新扁平化，
// 避免大型小区（上千户）每次勾选都深拷贝全部房屋对象造成主线程卡死。
flattenAllBuildingsHouses() {
  void this.treeDataVersion
  const version = this.treeDataVersion
  if (this._flatHouseList && this._flatHouseListVersion === version) {
    return this._flatHouseList
  }
  const list = []
  this.forEachHouseInTreeData((house, { floor, unit }) => {
    list.push({
      ...house,
      floorName: floor.floorName,
      unitName: unit.unitName || unit.unitId
    })
  })
  this._flatHouseList = list
  this._flatHouseListVersion = version
  return list
},

