// 列表展示「当前点中的楼幢」以及「已有勾选的其它楼幢」。每幢只扁平一次并复用行对象，勾选只同步 checked，不再每次深拷贝全部房屋。
cachedBuildingRows(building) {
  const { treeKey } = this.getDialogTreeMeta()
  const id = building?.[treeKey] ?? ''
  const cacheKey = `${this.treeDataVersion}:${id}`
  if (!this._buildingRowCache) this._buildingRowCache = {}
  const hit = this._buildingRowCache[cacheKey]
  if (hit) {
    hit.sources.forEach((house, index) => {
      hit.rows[index].checked = house.checked
    })
    return hit.rows
  }
  const rows = []
  const sources = []
  this.forEachFloorHouses(building.floorHouses, (house, { floor, unit }) => {
    sources.push(house)
    rows.push({
      ...house,
      floorName: floor.floorName,
      unitName: unit.unitName || unit.unitId
    })
  })
  this._buildingRowCache[cacheKey] = { rows, sources }
  return rows
},
flattenCheckedBuildingsHouses() {
  void this.treeDataVersion
  void this.buildingSelectRevision
  const { treeData, dialog, treeKey } = this.getDialogTreeMeta()
  const selectedKey = dialog?.treeSelection?.[treeKey]
  const list = []
  treeData.forEach((building) => {
    const id = building?.[treeKey]
    const state = this.buildingCheckCache.byId[id]
    const hasChecked = !!(state?.anySelected || state?.allSelected || state?.indeterminate)
    if (!hasChecked && id !== selectedKey) return
    list.push(...this.cachedBuildingRows(building))
  })
  return list
},

